methods.body:
s.log(LogInformational, "called")

var err error

// Prevent Open or other major Session functions from
// being called while Open is still running.
s.Lock()
defer s.Unlock()

// If the websock is already open, bail out here.
if s.wsConn != nil {
	return ErrWSAlreadyOpen
}

sequence := atomic.LoadInt64(s.sequence)

var gateway string
// Get the gateway to use for the Websocket connection
if sequence != 0 && s.sessionID != "" && s.resumeGatewayURL != "" {
	s.log(LogDebug, "using resume gateway %s", s.resumeGatewayURL)
	gateway = s.resumeGatewayURL
} else {
	if s.gateway == "" {
		s.gateway, err = s.Gateway()
		if err != nil {
			return err
		}
	}

	gateway = s.gateway
}

// Add the version and encoding to the URL
gateway += "?v=" + APIVersion + "&encoding=json"

// Connect to the Gateway
s.log(LogInformational, "connecting to gateway %s", gateway)
header := http.Header{}
header.Add("accept-encoding", "zlib")
s.wsConn, _, err = s.Dialer.Dial(gateway, header)
if err != nil {
	s.log(LogError, "error connecting to gateway %s, %s", s.gateway, err)
	s.gateway = "" // clear cached gateway
	s.wsConn = nil // Just to be safe.
	return err
}

s.wsConn.SetCloseHandler(func(code int, text string) error {
	return nil
})

defer func() {
	// because of this, all code below must set err to the error
	// when exiting with an error :)  Maybe someone has a better
	// way :)
	if err != nil {
		s.wsConn.Close()
		s.wsConn = nil
	}
}()

// The first response from Discord should be an Op 10 (Hello) Packet.
// When processed by onEvent the heartbeat goroutine will be started.
mt, m, err := s.wsConn.ReadMessage()
if err != nil {
	return err
}
e, err := s.onEvent(mt, m)
if err != nil {
	return err
}
if e.Operation != 10 {
	err = fmt.Errorf("expecting Op 10, got Op %d instead", e.Operation)
	return err
}
s.log(LogInformational, "Op 10 Hello Packet received from Discord")
s.LastHeartbeatAck = time.Now().UTC()
var h helloOp
if err = json.Unmarshal(e.RawData, &h); err != nil {
	err = fmt.Errorf("error unmarshalling helloOp, %s", err)
	return err
}

// Now we send either an Op 2 Identity if this is a brand new
// connection or Op 6 Resume if we are resuming an existing connection.
if s.sessionID == "" && sequence == 0 {

	// Send Op 2 Identity Packet
	err = s.identify()
	if err != nil {
		err = fmt.Errorf("error sending identify packet to gateway, %s, %s", s.gateway, err)
		return err
	}

} else {

	// Send Op 6 Resume Packet
	p := resumePacket{}
	p.Op = 6
	p.Data.Token = s.Token
	p.Data.SessionID = s.sessionID
	p.Data.Sequence = sequence

	s.log(LogInformational, "sending resume packet to gateway")
	s.wsMutex.Lock()
	err = s.wsConn.WriteJSON(p)
	s.wsMutex.Unlock()
	if err != nil {
		err = fmt.Errorf("error sending gateway resume packet, %s, %s", s.gateway, err)
		return err
	}

}

// A basic state is a hard requirement for Voice.
// We create it here so the below READY/RESUMED packet can populate
// the state :)
// XXX: Move to New() func?
if s.State == nil {
	state := NewState()
	state.TrackChannels = false
	state.TrackEmojis = false
	state.TrackMembers = false
	state.TrackRoles = false
	state.TrackVoice = false
	s.State = state
}

// Now Discord should send us a READY or RESUMED packet.
mt, m, err = s.wsConn.ReadMessage()
if err != nil {
	return err
}
e, err = s.onEvent(mt, m)
if err != nil {
	return err
}
if e.Type != `READY` && e.Type != `RESUMED` {
	// This is not fatal, but it does not follow their API documentation.
	s.log(LogWarning, "Expected READY/RESUMED, instead got:\n%#v\n", e)
}
s.log(LogInformational, "First Packet:\n%#v\n", e)

s.log(LogInformational, "We are now connected to Discord, emitting connect event")
s.handleEvent(connectEventType, &Connect{})

// A VoiceConnections map is a hard requirement for Voice.
// XXX: can this be moved to when opening a voice connection?
if s.VoiceConnections == nil {
	s.log(LogInformational, "creating new VoiceConnections map")
	s.VoiceConnections = make(map[string]*VoiceConnection)
}

// Create listening chan outside of listen, as it needs to happen inside the
// mutex lock and needs to exist before calling heartbeat and listen
// go rountines.
s.listening = make(chan interface{})

// Start sending heartbeats and reading messages from Discord.
go s.heartbeat(s.wsConn, s.listening, h.HeartbeatInterval)
go s.listen(s.wsConn, s.listening)

s.log(LogInformational, "exiting")
return nil

